INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(24500, 'koKR', 'Gniew Króla Lisza', 'Uther wiedział wiele o tym, jak można pokonać Arthasa. Trudno uwierzyć, że jest choć cień nadziei na pokonanie go u stóp jego własnego tronu. A kto przejmie koronę Króla Lisza, jeśli do tego dojdzie?$B$BWiele pytań pozostaje bez odpowiedzi, ale to, czego się $gdowiedziałeś:dowiedziałaś;, może okazać się kluczowe dla pokonania Arthasa. Musisz odnaleźć Jainę i uciec przed Królem Liszem, póki jeszcze jest czas.', 'Odnajdź lady Jainę Proudmoore i ucieknij z Sal Odbić', '', 'Porozmawiaj z lady Jainą Proudmoore w tylnej części Sal Odbić.', 'Odnajdź Jainę Proudmoore', 'Ucieknij przed Królem Liszem', '', '', 0),
(24711, 'koKR', 'Ostrze Mrozu', 'Musimy iść dalej, $gbohaterze:bohaterko;. Zaszliśmy tak daleko... jesteśmy tak blisko celu. Muszę na chwilę zostać, by odesłać Elandrę na statek powietrzny. Nie wiem, jak zdołamy uciec, skoro straciliśmy tylu ludzi, a tak niewielu zostało, by zabezpieczyć nam drogę – będziemy potrzebować każdej pomocy, jaką zdołają przysłać.$B$BIdź dalej. Spotkamy się w Salach Odbić.', 'Spotkaj się z lady Jainą Proudmoore przy wejściu do Sal Odbić.', '', '', '', '', '', '', 0),
(24713, 'koKR', 'Ostrze Mrozu', 'Idź dalej, miecz jest blisko.$B$BMuszę na chwilę zostać, by odesłać jedną z moich mrocznych tropicielek na statek powietrzny. Skoro całe nasze mięso armatnie przepadło, nie dam się zaskoczyć – będziemy potrzebować każdej pomocy, jaką zdołają przysłać.$B$BIdź. Spotkamy się w Salach Odbić.', 'Spotkaj się z lady Sylwaną Bieżywiatr tuż za wejściem do Sal Odbić.', '', '', '', '', '', '', 0),
(24802, 'koKR', 'Gniew Króla Lisza', 'Uther wiedział wiele o tym, jak można pokonać Arthasa. Trudno uwierzyć, że jest choć cień nadziei na pokonanie go u stóp jego własnego tronu. A kto przejmie koronę Króla Lisza, jeśli do tego dojdzie?$B$BWiele pytań pozostaje bez odpowiedzi, ale to, czego się $gdowiedziałeś:dowiedziałaś;, może okazać się kluczowe dla pokonania Arthasa. Musisz odnaleźć Sylwanę i uciec przed Królem Liszem, póki jeszcze jest czas.', 'Odnajdź lady Sylwanę Bieżywiatr i ucieknij z Sal Odbić', '', 'Porozmawiaj z lady Sylwaną Bieżywiatr w tylnej części Sal Odbić.', 'Odnajdź Sylwanę Bieżywiatr', 'Ucieknij przed Królem Liszem', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(24500, 'koKR', '<Jaina wciąż łapie oddech.>$B$BLedwie mogę uwierzyć, że wciąż żyjemy. To było głupie z mojej strony, że za nim poszłam. Popełniłam ten błąd zbyt wiele razy. A ty... to było lekkomyślne, że $gruszyłeś:ruszyłaś; za mną, zamiast uciec z tymi informacjami! Ale... cóż... dziękuję. Naprawdę $gjesteś bohaterem:jesteś bohaterką;.$B$BDzięki wskazówkom Uthera mamy szansę pokonać Arthasa. Wszystkie życia stracone dzisiaj nie poszły na marne.', 0),
(24711, 'koKR', 'Sale Odbić. Nareszcie.$B$BDaj znać, gdy będziesz $ggotów:gotowa;. Arthasa może tu nie być, ale naiwnością byłoby sądzić, że zostawiłby Ostrze Mrozu zupełnie bez straży.', 0),
(24713, 'koKR', 'Sale Odbić. Nareszcie.$B$BDaj znać, gdy będziesz $ggotów:gotowa;, $N. Nie jestem na tyle naiwna, by sądzić, że Arthas zostawił swój cenny miecz zupełnie bez straży.', 0),
(24802, 'koKR', 'Znów zemsta wymyka mi się z rąk. Trudno uwierzyć, jak bardzo urósł w siłę.$B$BTo było głupie, że po mnie $gprzyszedłeś:przyszłaś;, ale dobrze wiedzieć, że wśród czempionów Hordy są jeszcze tacy, którzy nie są bezużytecznymi tchórzami. Informacje od Uthera mogą okazać się kluczem do ostatecznego zabicia Arthasa, choć coraz wyraźniej widać, że Horda nie dokona tego sama.$B$BIdź, $N. Spodziewam się, że twoje umiejętności wkrótce znów będą potrzebne.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(24500, 'koKR', 'Musimy przekazać te informacje Przymierzu! Mogą okazać się kluczem do pokonania Arthasa.', 0);
