INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(36821, 'koKR', '', 'Jest zbyt potężny. Musimy natychmiast opuścić to miejsce! Moja magia utrzyma go w miejscu tylko przez krótką chwilę. Szybko, bohaterowie!', 0),
(36885, 'koKR', 'Jesteśmy gotowi! Ruszajmy!', 'Jesteśmy gotowi! Ruszajmy!', 0),
(36990, 'koKR', '', 'Wybaczcie mi, bohaterowie. Powinnam była posłuchać Uthera. Ja... po prostu musiałam zobaczyć to na własne oczy. Spojrzeć mu w oczy ostatni raz. Przepraszam.', 0),
(36991, 'koKR', '', 'Teraz wiemy, co należy zrobić. Przekażę te wieści królowi Varianowi i najwyższemu lordowi Fordringowi.', 0),
(36992, 'koKR', '', 'To... to ślepy zaułek. Nie mamy wyboru, musimy walczyć. Przygotujcie się, bohaterowie, bo to nasz ostatni bój!', 0),
(36994, 'koKR', 'Nie ma dokąd uciec... Teraz należycie do mnie!', '', 0),
(37168, 'koKR', '', 'Jest... zbyt potężny. Bohaterowie, szybko... do mnie! Musimy natychmiast opuścić to miejsce! Zrobię, co w mojej mocy, by go zatrzymać, gdy będziemy uciekać.', 0),
(37169, 'koKR', '', 'Nie zdołam go długo powstrzymać, musimy natychmiast uciekać!', 0),
(37170, 'koKR', '', 'PRZEKLĘTY ŚLEPY ZAUŁEK! A więc tak to się kończy. Przygotujcie się, bohaterowie, bo dziś stoczymy nasz ostatni bój!', 0),
(37171, 'koKR', '', 'Jesteśmy bezpieczni... na razie. Od naszej ostatniej bitwy jego siła wzrosła dziesięciokrotnie. Zniszczenie Króla Lisza będzie wymagało potężnej armii. Armii większej, niż zdoła zebrać nawet Horda.', 0),
(37172, 'koKR', 'Twoi sojusznicy przybyli, Jaino, tak jak obiecałaś. Wszyscy staniecie się potężnymi sługami Plagi.', '', 0),
(37173, 'koKR', 'Nie popełnię dwa razy tego samego błędu, Sylwano. Tym razem nie będzie ucieczki. Wszyscy będziecie mi służyć po śmierci!', '', 0),
(37174, 'koKR', 'Czekają was zimne objęcia śmierci.', '', 0),
(37175, 'koKR', 'Poddajcie się chłodowi grobu.', '', 0),
(37176, 'koKR', 'Kolejny ślepy zaułek.', '', 0),
(37177, 'koKR', 'Nie ma ucieczki!', '', 0),
(37201, 'koKR', 'Stój! Nie nieś tego ostrza ani kroku dalej!', '', 0),
(37202, 'koKR', 'Czy zdajesz sobie sprawę, co $gzrobiłeś:zrobiłaś;?', '', 0),
(37204, 'koKR', '$GWykułeś:Wykułaś; to ostrze z saronitu, krwi samego przedwiecznego boga. Moc Króla Lisza przyzywa tę broń.', '', 0),
(37205, 'koKR', 'Jest tylko jeden sposób, by oczyścić ten miecz. Spiesz do Słonecznej Studni i zanurz ostrze w jej wodach.', '', 0),
(37206, 'koKR', 'Nie mogę już dłużej opierać się wezwaniu Ostrza Mrozu...', '', 0),
(37478, 'koKR', '', 'Mroźnej Królowej już nie ma. Musimy iść dalej – nasz cel jest blisko.', 0),
(37479, 'koKR', '', 'Bohaterowie, do mnie!', 0),
(37480, 'koKR', '', 'Nie... nie zdołałam ich ocalić... Niech cię szlag, Arthasie! NIECH CIĘ SZLAG!', 0),
(37540, 'koKR', '', 'Schowajcie się za mną! Szybko!', 0),
(37541, 'koKR', '', 'Myślałam, że nigdy się nie zamknie. Wreszcie Sindragosa uciszyła tego gadatliwego głupca. Do Sal Odbić, czempioni! Nasz cel jest blisko... wyczuwam go.', 0),
(37564, 'koKR', '', 'Stać tak blisko ostrza, które zakończyło moje życie... Ból... powraca.', 0),
(37566, 'koKR', 'Czy możesz wyjąć miecz?', 'Czy możesz wyjąć miecz?', 0),
(37567, 'koKR', 'Mroczna Pani, chyba słyszę, że nadchodzi Arthas. Cokolwiek zamierzasz zrobić, zrób to szybko.', 'Mroczna Pani, chyba słyszę, że nadchodzi Arthas. Cokolwiek zamierzasz zrobić, zrób to szybko.', 0),
(37568, 'koKR', '', 'Nie... nie wierzę! Ostrze Mrozu stoi przed nami – bez straży – tak jak twierdził gnom. Chodźcie, bohaterowie!', 0),
(37569, 'koKR', '', 'Stać tak blisko ostrza, które zakończyło moje życie... Ból... powraca.', 0),
(37570, 'koKR', '', 'Nie śmiem go dotknąć. Odsuńcie się! Odsuńcie się, gdy spróbuję porozumieć się z ostrzem! Może to w nim kryje się nasze ocalenie...', 0),
(37571, 'koKR', '', 'Uther... Uther Światłodzierżca. Jak...', 0),
(37572, 'koKR', '', 'Król Lisz tu jest? Zatem dziś wypełni się moje przeznaczenie!', 0),
(37573, 'koKR', '', 'Musi być jakiś sposób...', 0),
(37575, 'koKR', '', 'Mroźny Tron...', 0),
(37576, 'koKR', '', 'Tak łatwo mi nie uciekniesz, Arthasie! Dokonam zemsty!', 0),
(37583, 'koKR', 'Ostrożnie, dziewczyno. Słyszałem już, jak mówiono, że ten przeklęty miecz nas ocali. Rozejrzyj się i zobacz, co zrodziło się z Ostrza Mrozu.', '', 0),
(37584, 'koKR', 'Nie masz wiele czasu. Król Lisz widzi to, co widzi miecz. Wkrótce tu będzie.', '', 0),
(37585, 'koKR', 'Nie pokonasz Króla Lisza. Nie tutaj. Byłoby głupotą próbować. Zabije tych, którzy za tobą idą, i wskrzesi ich jako potężnych żołnierzy Plagi. Ale ciebie, Sylwano, czekałaby nagroda gorsza od poprzedniej.', '', 0),
(37586, 'koKR', 'Być może, ale wiedz jedno: zawsze musi istnieć Król Lisz. Nawet gdybyś powaliła Arthasa, ktoś inny musiałby zająć jego miejsce, bo bez kontroli Króla Lisza Plaga zalałaby ten świat niczym szarańcza, niszcząc wszystko, czego dotknie.', '', 0),
(37587, 'koKR', 'Nie wiem, Królowo Banshee. Podejrzewam, że jedynie ta cząstka Arthasa, która może jeszcze tkwić w Królu Liszu, powstrzymuje Plagę przed unicestwieniem Azeroth.', '', 0),
(37588, 'koKR', 'Niestety, jedynym sposobem na pokonanie Króla Lisza jest zniszczenie go w miejscu, w którym został stworzony.', '', 0),
(37589, 'koKR', 'Tak. AAAAARGH... On... On nadchodzi. Musisz... Musisz...', '', 0),
(37591, 'koKR', '', 'Chłód tego miejsca... Czuję, jak krew zamarza mi w żyłach.', 0),
(37592, 'koKR', '', 'Co to jest? Tam, przed nami! Czy to możliwe? Bohaterowie, do mnie!', 0),
(37593, 'koKR', '', 'Ostrze Mrozu: miecz, który zniszczył nasze królestwo...', 0),
(37594, 'koKR', '', 'Odsuńcie się! Dotknijcie tego ostrza, a wasza dusza zostanie naznaczona na całą wieczność! Muszę spróbować porozumieć się z duchami uwięzionymi w Ostrzu Mrozu. Dajcie mi trochę miejsca. Cofnijcie się, proszę.', 0),
(37595, 'koKR', '', 'Uther! Drogi Utherze! Ja... tak mi przykro.', 0),
(37596, 'koKR', '', 'Arthas tu jest? Może ja...', 0),
(37597, 'koKR', '', 'Ale Utherze, jeśli jest jakakolwiek nadzieja, by dotrzeć do Arthasa... Ja... muszę spróbować.', 0),
(37598, 'koKR', '', 'Powiedz mi jak, Utherze? Jak mam zniszczyć mojego księcia? Mojego...', 0),
(37599, 'koKR', '', 'Masz rację, Utherze. Wybacz mi. Ja... nie wiem, co we mnie wstąpiło. Przekażemy te informacje królowi i rycerzom, którzy walczą z Plagą w Cytadeli Lodowej Korony.', 0),
(37600, 'koKR', '', 'Kto mógłby udźwignąć takie brzemię?', 0),
(37601, 'koKR', '', 'Zatem może wciąż jest nadzieja...', 0),
(37602, 'koKR', '', 'Nie odmówisz mi tego, Arthasie! Muszę wiedzieć... Muszę się dowiedzieć...', 0),
(37603, 'koKR', 'Jaina! Czy to naprawdę ty?', '', 0),
(37604, 'koKR', 'Jaino, nie masz wiele czasu. Król Lisz widzi to, co widzi miecz. Wkrótce tu będzie.', '', 0),
(37605, 'koKR', 'Nie, dziewczyno. Arthasa tu nie ma. Arthas jest jedynie obecnością w umyśle Króla Lisza. Gasnącą obecnością...', '', 0),
(37606, 'koKR', 'Jaino, posłuchaj mnie. Musisz zniszczyć Króla Lisza. Nie da się z nim pertraktować. Zabije ciebie i twoich sojuszników, a potem wskrzesi was wszystkich jako potężnych żołnierzy Plagi.', '', 0),
(37607, 'koKR', 'Opamiętaj się, dziewczyno. Musisz zniszczyć Króla Lisza w miejscu, w którym połączył się z Ner\'zhulem – na szczycie iglicy, przy Mroźnym Tronie. To jedyny sposób.', '', 0),
(37608, 'koKR', 'Jest... jeszcze coś, co powinnaś wiedzieć o Królu Liszu. Nie wolno nigdy utracić kontroli nad Plagą. Nawet gdybyś powaliła Króla Lisza, ktoś inny musiałby zająć jego miejsce. Bo bez kontroli swego pana Plaga rozpleniłaby się po całym świecie, niszcząc wszelkie życie.', '', 0),
(37609, 'koKR', 'Wielkie poświęcenie szlachetnej duszy...', '', 0),
(37610, 'koKR', 'Nie wiem, Jaino. Podejrzewam, że jedynie ta cząstka Arthasa, która może jeszcze tkwić w Królu Liszu, powstrzymuje Plagę przed unicestwieniem Azeroth.', '', 0),
(37611, 'koKR', 'Nie, Jaino! AAAAARGH... On... On nadchodzi. Musisz... Musisz...', '', 0),
(37613, 'koKR', 'MILCZ, PALADYNIE!', '', 0),
(37614, 'koKR', 'A więc chcesz porozmawiać ze zmarłymi? Twoje życzenie się spełni.', '', 0),
(37615, 'koKR', 'Falryku. Marwynie. Gdy skończycie, przynieście ich zwłoki do mojej komnaty.', '', 0),
(37931, 'koKR', 'Mężczyźni, kobiety i dzieci... Nikogo nie oszczędził gniew pana. Wasza śmierć nie będzie inna.', '', 0),
(37941, 'koKR', 'Skomlący robaku!', '', 0),
(37942, 'koKR', 'Dzieci Stratholmu walczyły z większą zaciekłością!', '', 0),
(37943, 'koKR', 'Marwynie, dokończ ich...', '', 0),
(37944, 'koKR', 'Żołnierze Lordaeronu, powstańcie na wezwanie swego pana!', '', 0),
(37945, 'koKR', 'Rozpacz... jakże smakowita...', '', 0),
(37946, 'koKR', 'Strach... jakże upajający...', '', 0),
(37948, 'koKR', 'Znajdziecie tu tylko śmierć!', '', 0),
(37949, 'koKR', 'Widziałem to samo spojrzenie w jego oczach, gdy umierał. Terenas ledwie mógł w to uwierzyć.', '', 0),
(37950, 'koKR', 'Udławcie się swoim cierpieniem!', '', 0),
(37951, 'koKR', 'Tak... Biegnijcie... Biegnijcie na spotkanie przeznaczenia... Jego gorzkie, zimne objęcia już na was czekają.', '', 0),
(37952, 'koKR', 'Pan przyjrzał się swemu królestwu i uznał je za... niewystarczające. Jego wyrok był szybki i bezlitosny: ŚMIERĆ WSZYSTKIM!', '', 0),
(37953, 'koKR', 'Jak sobie życzysz, mój panie.', '', 0),
(37954, 'koKR', 'Wasze ciało zgnije na waszych oczach!', '', 0),
(37955, 'koKR', 'Obróćcie się w nicość!', '', 0),
(38383, 'koKR', 'Pani, chyba słyszę, że nadchodzi Arthas. Cokolwiek zamierzasz zrobić, zrób to szybko.', 'Pani, chyba słyszę, że nadchodzi Arthas. Cokolwiek zamierzasz zrobić, zrób to szybko.', 0),
(38442, 'koKR', 'Z każdą chwilą, którą tu zwlekasz, Quel\'Delar wchłania zło tego miejsca.', '', 0),
(38525, 'koKR', 'Nasza męka jest wieczna.', 'Nasza męka jest wieczna.', 0),
(38526, 'koKR', 'To nie jest nasz ostatni spoczynek.', 'To nie jest nasz ostatni spoczynek.', 0),
(38527, 'koKR', 'Po śmierci wszyscy służą panu.', 'Po śmierci wszyscy służą panu.', 0),
(38528, 'koKR', 'To tylko krótkie wytchnienie...', 'To tylko krótkie wytchnienie...', 0),
(38529, 'koKR', 'Nasze dusze nigdy nie zostaną uwolnione.', 'Nasze dusze nigdy nie zostaną uwolnione.', 0),
(38536, 'koKR', '', 'Zniszczę tę barierę. Musicie powstrzymać nieumarłych!', 0),
(38537, 'koKR', '', 'Kolejna lodowa ściana! Nie pozwólcie nieumarłym przerwać moich inkantacji, żebym mogła ją zburzyć.', 0),
(38538, 'koKR', '', 'Już prawie jesteśmy... Nie poddawajcie się!', 0),
(38539, 'koKR', '', 'Twoje bariery długo nas nie zatrzymają, potworze! Roztrzaskam je wszystkie!', 0),
(38540, 'koKR', '', 'Żaden mur nie zatrzyma Królowej Banshee. Trzymajcie nieumarłych z dala, bohaterowie. Zburzę tę barierę!', 0),
(38541, 'koKR', '', 'Kolejna bariera? Trzymajcie się, czempioni. Zburzę ten mur.', 0),
(38542, 'koKR', '', 'Nudzą mnie te gierki, Arthasie! Twoje mury mnie nie powstrzymają!', 0),
(38543, 'koKR', '', 'Nie przeszkodzisz nam w ucieczce, łotrze! Trzymajcie nieumarłych z dala ode mnie, a ja zburzę tę barierę.', 0),
(38551, 'koKR', '', 'Przed nami jest przejście. SZYBKO!', 0),
(38623, 'koKR', 'Duchy pojawiają się i otaczają ołtarz!', 'Duchy pojawiają się i otaczają ołtarz!', 0),
(38664, 'koKR', 'Nie jesteście godni stanąć przed Królem Liszem!', '', 0),
(38668, 'koKR', 'Jak długo zdołasz się temu opierać?', '', 0),
(38669, 'koKR', 'Powstańcie, sługi. Nie pozwólcie im przejść.', '', 0),
(38670, 'koKR', 'Sługi, pochwyćcie ich. Przynieście mi ich zwłoki.', '', 0);
